
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3lyp5_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3lyp5", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.517627861558873e+00, -3.451805780351132e+00, -3.359621190706797e+00, -3.232022247514612e+00, -3.058358229478616e+00, -2.827644790871459e+00, -2.531526604891131e+00, -2.169508563622006e+00, -1.755528899807465e+00, -1.319562983413713e+00, -8.923152987516280e-01, -6.026247222738668e-01, -5.195437291020145e-01, -4.332910432294361e-01, -3.160839670543976e-01, -1.999128060303496e-01, -1.172752157926456e-01, -7.350247157213260e-02, -4.490342264755737e-02, -3.015467802977682e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


